import unittest
import mock
from mock import patch
from taf.ul.oam.selenium_coam.pages.options import (GeneralPage, GeneralPageViewPanel,
                                                    SessionListPage, SessionListPageViewPanel)


class TestGeneralPage(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.general_page = GeneralPage()

    def test_get_lock_screen_time(self):
        self.general_page._view_panel.get_lock_screen_time = mock.Mock(return_value=10)

        result = self.general_page.get_lock_screen_time()
        self.assertEqual(10, result)

    def test_set_lock_screen_time(self):
        lock_time = 10
        enable_debug_log = False
        self.general_page._view_panel.set_lock_screen_time = mock.Mock()

        self.general_page.set_lock_screen_time(lock_time, enable_debug_log)
        self.general_page._view_panel.set_lock_screen_time.assert_called_with(10, False)


class TestGeneralPageViewPanel(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.general_page_view_panel = GeneralPageViewPanel()

    def test_get_lock_screen_time(self):
        self.general_page_view_panel.wait_for_visibility_by_xpath = mock.Mock()
        self.general_page_view_panel.get_attribute_by_xpath = mock.Mock()

        self.general_page_view_panel.get_lock_screen_time()
        self.general_page_view_panel.wait_for_visibility_by_xpath.assert_called_once()
        self.general_page_view_panel.get_attribute_by_xpath.assert_called_once()

    def test_set_lock_screen_time(self):
        lock_time = 10
        enable_debug_log = False
        self.general_page_view_panel.insert_text_to_enable_element = mock.Mock()
        self.general_page_view_panel.select_checkbox_by_specified_status = mock.Mock()
        self.general_page_view_panel.click_enabled_element = mock.Mock()

        self.general_page_view_panel.set_lock_screen_time(lock_time, enable_debug_log)
        self.general_page_view_panel.insert_text_to_enable_element.assert_called_once()
        self.general_page_view_panel.select_checkbox_by_specified_status.set_lock_screen_time()
        self.general_page_view_panel.click_enabled_element.assert_called_once()


class TestSessionListPage(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.sessions_list_page = SessionListPage()

    def test_get_sessions_list_detail_info(self):
        self.sessions_list_page._view_panel.get_sessions_list_detail_info = mock.Mock()

        self.sessions_list_page.get_sessions_list_detail_info()
        self.sessions_list_page._view_panel.get_sessions_list_detail_info.assert_called_once()


class TestSessionListPageViewPanel(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.sessions_list_page_view_panel = SessionListPageViewPanel()

    def test_get_sessions_list_detail_info(self):
        self.sessions_list_page_view_panel._get_session_title = mock.Mock(return_value=['a', 'b'])
        self.sessions_list_page_view_panel._get_session_value = mock.Mock(return_value=[[1, 2], [3, 4]])

        result = self.sessions_list_page_view_panel.get_sessions_list_detail_info()
        self.sessions_list_page_view_panel._get_session_title.assert_called_once()
        self.sessions_list_page_view_panel._get_session_value.assert_called_once()
        self.assertEqual(result, [{'a': 1, 'b': 2}, {'a': 3, 'b': 4}])
